/**
 * Anthropic Chat Model Node - Version 1.6
 * Language Model Anthropic
 */


export interface LcLmChatAnthropicV16Params {
/**
 * The model. Choose from the list, or specify an ID. &lt;a href="https://docs.anthropic.com/claude/docs/models-overview"&gt;Learn more&lt;/a&gt;.
 * @builderHint When extended thinking is needed, use Adaptive mode and choose an Effort level. Keep a working or explicitly requested model unless provider evidence shows it is unavailable or unsuitable. When choosing a new model, select a current stable model supported by this node version, the configured API, and the required operation. Use the declared model-list lookup with the connected credential when available. Gateway credits can restrict that list. For a new choice without credentials, use current provider catalog information. Choose a model that fits the task and budget. Copy the exact model ID. Do not rely on node defaults, invent model IDs, or treat an unfamiliar model as invalid.
 * @searchListMethod searchModels
 * @default {"mode":"list","value":"claude-sonnet-5","cachedResultName":"Claude Sonnet 5"}
 */
    model?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Additional options to add
 * @default {}
 */
    options?: {
    /** The maximum number of tokens to generate in the completion
     * @default 4096
     */
    maxTokensToSample?: number | Expression<number>;
    /** Controls randomness: Lowering results in less random completions. As the temperature approaches zero, the model will become deterministic and repetitive. Not supported on newer Anthropic models (Claude Opus 4.7+, Claude Sonnet 5+) — ignored there.
     * @displayOptions.hide { thinking: [true], thinkingMode: ["adaptive", "manual"] }
     * @default 0.7
     */
    temperature?: number | Expression<number>;
    /** Used to remove "long tail" low probability responses. Defaults to -1, which disables it. Not supported on newer Anthropic models (Claude Opus 4.7+, Claude Sonnet 5+) — ignored there.
     * @displayOptions.hide { thinking: [true], thinkingMode: ["adaptive", "manual"] }
     * @default -1
     */
    topK?: number | Expression<number>;
    /** Controls diversity via nucleus sampling: 0.5 means half of all likelihood-weighted options are considered. We generally recommend altering this or temperature but not both. Not supported on newer Anthropic models (Claude Opus 4.7+, Claude Sonnet 5+) — ignored there.
     * @displayOptions.hide { thinking: [true], thinkingMode: ["adaptive", "manual"] }
     * @default 1
     */
    topP?: number | Expression<number>;
    /** How extended thinking is configured. Leave the option unset to use the model default.
     * @default disabled
     */
    thinkingMode?: 'disabled' | 'adaptive' | 'manual' | Expression<string>;
    effort?:
      /** Effort level for adaptive thinking
       * @displayOptions.show { thinkingMode: ["adaptive"], /model.value: [{"_cnd":{"includes":"opus"}}] }
       * @default medium
       */
      | 'low' | 'medium' | 'high' | 'xhigh' | 'max' | Expression<string>
      /** Effort level for adaptive thinking
       * @displayOptions.show { thinkingMode: ["adaptive"], /model.value: [{"_cnd":{"regex":"^(?!.*opus).*"}}] }
       * @default medium
       */
      | 'low' | 'medium' | 'high' | Expression<string>;
    /** Maximum tokens used for thinking. Manual mode is rejected by Opus 4.7+.
     * @displayOptions.show { thinkingMode: ["manual"] }
     * @default 1024
     */
    thinkingBudget?: number | Expression<number>;
    /** Whether the model should stream its response over Server-Sent Events instead of returning a single non-streamed payload. Final output shape is unchanged.
     * @default false
     */
    streaming?: boolean | Expression<boolean>;
    /** Whether to cache the system prompt, tool definitions, and conversation history between requests using &lt;a href="https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching"&gt;Anthropic prompt caching&lt;/a&gt;. The value sets how long cached content stays valid before it has to be written again.
     * @default disabled
     */
    promptCaching?: 'disabled' | '5m' | '1h' | Expression<string>;
  };
}

export interface LcLmChatAnthropicV16Credentials {
  anthropicApi: CredentialReference;
}

interface LcLmChatAnthropicV16NodeBase {
  type: '@n8n/n8n-nodes-langchain.lmChatAnthropic';
  version: 1.6;
}

export type LcLmChatAnthropicV16ParamsNode = LcLmChatAnthropicV16NodeBase & {
  config: NodeConfig<LcLmChatAnthropicV16Params> & { credentials?: LcLmChatAnthropicV16Credentials };
};

export type LcLmChatAnthropicV16Node = LcLmChatAnthropicV16ParamsNode;